mapper.select:
SELECT id, session_id, user_id, summary_text, key_points, created_at, updated_at
FROM session_summary
WHERE id = #{id}

SELECT id, session_id, user_id, summary_text, key_points, created_at, updated_at
FROM session_summary
WHERE session_id = #{sessionId}

SELECT id, session_id, user_id, summary_text, key_points, created_at, updated_at
FROM session_summary
WHERE user_id = #{userId}
ORDER BY updated_at DESC
LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*)
FROM session_summary
WHERE user_id = #{userId}
